def solve(data):
    s, t = data["s"], data["t"]
    from collections import Counter
    need = Counter(t)
    missing = len(t)
    left = 0
    best = ""
    for right, c in enumerate(s):
        if need[c] > 0:
            missing -= 1
        need[c] -= 1
        while missing == 0:
            if best == "" or right - left + 1 < len(best):
                best = s[left:right + 1]
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return best

