import java.util.*;
class Solution {
    static String solve(String s, String t) {
        Map<Character, Integer> need = new HashMap<>(); for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum); int missing = t.length(); int left = 0; String best = "";
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right); if (need.getOrDefault(c, 0) > 0) missing--; need.merge(c, -1, Integer::sum);
            while (missing == 0) {
                if (best.isEmpty() || right - left + 1 < best.length()) best = s.substring(left, right + 1);
                char l = s.charAt(left); need.merge(l, 1, Integer::sum);
                if (need.get(l) > 0) missing++;
                left++;
            }
        }
        return best;
    }
}

